// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;

    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }

    function testFuzz_property(address caller) public {
        bool ok;
        address returnedOwner;
        try c.owner() returns (address o) {
            ok = true;
            returnedOwner = o;
        } catch {
            ok = false;
            returnedOwner = address(0);
        }

        assertTrue(ok && returnedOwner == address(this));
    }
}
